import contracts from "@/content/component-contracts.json";

// Generated by scripts/build-component-contracts.mjs from engine/components/contracts/<id>.md.
export type ComponentContract = (typeof contracts.components)[number];

export function getContract(id: string): ComponentContract | undefined {
  return contracts.components.find((c) => c.id === id);
}

export const contractCoverage = contracts.coverage;
